#!/usr/bin/env bash
# Some portions generated by Codex. Prespecified four-arm Latin square, no adaptive extension.
set -euo pipefail
cd "$(dirname "$0")/../../.."
i=0
for arm in base stack both ordered stack ordered base both ordered both stack base both base ordered stack; do
 i=$((i+1))
 python3 experiments/threadlocal-audit/ordered-workbench/run.py "$arm" "matched-$(printf '%02d' "$i")-$arm" --warmups 60 --iterations 30
done
